    const id = F.id, e = entidadeDe('CLIENTE', id) || { cliente: id }, a = abcPorId(), r = a && a.get(id), t = tratativaPorCliente().get(id);
    const abc = curva();
    const atividades = ((C.state.agendaWin && C.state.agendaWin.items) || []).concat(C.state.overdue || []).filter((x) => x.entidadeId === id);
    const vistos = new Set(), ativ = atividades.filter((x) => (vistos.has(x.agendaId) ? false : vistos.add(x.agendaId))).sort((x, y) => ordHora(y, x));
    const hist = [];
    ativ.forEach((x) => hist.push([x.dataProgramada, `${tipoIc(x.tipoAtividadeId)} ${esc(tipoInfo(x.tipoAtividadeId).nome)}${x.resultadoNome ? ' · ' + esc(x.resultadoNome) : statusAt(x) === 'plan' ? ' · planejada' : statusAt(x) === 'cancel' ? ' · cancelada' : ''}`, esc(x.responsavelNome || ''), x.agendaId]));
    if (F.hist) {
      F.hist.notas.forEach((n) => hist.push([text(n.dataHora).slice(0, 10), `${ci('edit', V.purple, V.orange, 'sm')} Anotação`, esc(n.texto), '']));
      F.hist.checks.forEach((c) => hist.push([text(c.data || c.criadoEm).slice(0, 10), `${ci('ok', V.teal, V.orange, 'sm')} Checklist · ${esc(c.resultadoVisita || c.statusVisita || '')}`, esc(c.observacaoCurta || c.oportunidadePrincipal || ''), '']));
    }
    hist.sort((x, y) => String(y[0]).localeCompare(String(x[0])));
    const ctr = norm(e.temContrato) === 'sim' || (r && r.contrato);
    camada().innerHTML = `<div class="backdrop" data-f-fechar style="justify-content:flex-end;padding:0"></div><aside class="drawer" role="dialog" aria-modal="true" aria-labelledby="cx-dt">
      <div class="dr-h"><div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start"><div style="display:flex;gap:10px;min-width:0">${ib('store', V.blue, V.orange)}<div style="min-width:0"><h2 id="cx-dt" style="font-size:18px">${esc(C.entityName(e) || e.cliente || id)}</h2><p class="muted" style="font-size:12.5px;margin-top:3px">LOCAL ${esc(NOME_LOCAL[norm(e.local).toUpperCase()] || e.local || localAtual())} · ${esc((r && r.intermediador) || e.intermediador || 'sem intermediador')} · ${ctr ? 'contrato ativo' : 'sem contrato'}</p></div></div><button type="button" class="btn ghost sm" data-f-fechar aria-label="Fechar">${ic('x')}</button></div>
        <div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:10px">${e.acaoEngine || e.acao ? acChip(e.acaoEngine || e.acao) : ''}${prChip(e.prioridadeFila)}${r ? abcChip(r.abc) : ''}${e.curva ? `<span class="chip">Curva 30D ${esc(e.curva)}</span>` : ''}${r && r.novo ? '<span class="chip novo">NOVO</span>' : ''}</div>
        <div style="display:flex;gap:8px;margin-top:12px;flex-wrap:wrap"><button type="button" class="btn sm pri" data-cx-nova-cli="${esc(id)}">${ic('cal', 'sm')}Agendar</button>${waBtn(e.whatsapp, C.entityName(e), '', false)}${C.can('canEditClients') ? `<button type="button" class="btn sm" data-f-editar="${esc(id)}">${ci('edit', V.purple, V.orange, 'sm')}${text(e.whatsapp) ? 'Editar cadastro' : 'Completar cadastro'}</button>` : ''}</div></div>
      ${fichaCadastroHtml(e)}
      <div class="dr-s"><h3 style="margin-bottom:10px;display:flex;gap:8px;align-items:center">${ib('trend-up', V.blue, V.orange, 'sm')}Postagens (Visão 360)</h3>
        ${r ? `<div class="kv"><div><small>Fat. 12M</small><b class="num" style="color:${V.blue}">${brlK(r.tV)}</b></div><div><small>Objetos 12M</small><b class="num" style="color:${V.orange}">${n0(r.tQ)}</b></div><div><small>Ticket</small><b class="num" style="color:${V.teal}">${brl(r.tk, 2)}</b></div></div>
          <div id="cx-ch-ficha" class="chx" style="height:130px;margin-top:6px" role="img" aria-label="Faturamento mensal do cliente"></div>`
          : abc ? `<p class="muted" style="font-size:12.5px">Sem postagens em ${esc(nomeLocais())} nos últimos 12 meses.</p>` : (curva(), carregandoHtml())}
        ${e.motivoRegra ? `<p class="muted" style="font-size:12px;margin-top:6px">Motivo da regra: ${esc(e.motivoRegra)}.</p>` : ''}</div>
      <div class="dr-s"><h3 style="margin-bottom:8px;display:flex;gap:8px;align-items:center">${ib('kanban', V.purple, V.orange, 'sm')}Tratativa</h3>
        ${t ? `<div class="stage" style="margin-bottom:8px"><i style="background:${corEtapa(t.etapaId)}"></i>${esc(nomeEtapa(t.etapaId))}${t.abertaEm ? ' desde ' + fmtD(t.abertaEm) : ''}${t.responsavelId ? ' · ' + esc(C.responsibleDisplay(t.responsavelId)) : ''}</div>
          ${t.proximaAtividade ? `<div class="stage">${proxHtml(t.proximaAtividade)}</div>` : `<div style="display:flex;gap:6px;align-items:center;color:${V.red};font-weight:700;font-size:12.5px">${ci('alert', V.red, V.orange, 'sm')}Sem próxima atividade</div>`}
          <button type="button" class="btn sm" style="margin-top:10px" data-f-trt="${esc(t.tratativaId)}">${ci('open', V.blue, V.orange, 'sm')}Abrir tratativa e checklist</button>`
          : `<p class="muted" style="font-size:12.5px;margin-bottom:8px">Ainda sem tratativa.</p>${C.can('canMoveFunnel') || C.can('canEditClients') ? `<button type="button" class="btn sm" data-cx-assumir="${esc(id)}">${ci('hand', V.purple, V.orange, 'sm')}Assumir</button>` : ''}`}</div>
      <div class="dr-s"><h3 style="margin-bottom:8px;display:flex;gap:8px;align-items:center">${ib('clock', V.teal, V.orange, 'sm')}Histórico</h3>
        <div class="list">${hist.slice(0, 15).map((h) => `<div class="li" style="grid-template-columns:52px 1fr" ${h[3] ? `data-cx-ag="${esc(h[3])}"` : ''}><span class="s">${fmtD(h[0])}</span><div style="min-width:0"><div class="n" style="white-space:normal">${h[1]}</div>${h[2] ? `<div class="s">${h[2]}</div>` : ''}</div></div>`).join('') || (F.hist ? '<div class="empty">Sem histórico ainda.</div>' : carregandoHtml())}</div></div>
    </aside>`;
    document.body.style.overflow = 'hidden';
    if (r && abc) setTimeout(() => graficoFicha(r, abc), 0);
